const { createQuestionRepository, toPublicQuestion } = require("./repositories/questionRepository");

const expectedColumns = {
  id: ["int unsigned", "NO"],
  etapa_escolar: ["enum('fundamental','médio','superior')", "NO"],
  nivel_estrutural: ["tinyint unsigned", "NO"],
  enunciado: ["text", "NO"],
  opcao_a: ["varchar(500)", "NO"],
  opcao_b: ["varchar(500)", "NO"],
  opcao_c: ["varchar(500)", "NO"],
  opcao_d: ["varchar(500)", "NO"],
  resposta_correta: ["enum('a','b','c','d')", "NO"],
  explicacao: ["text", "YES"],
  tags: ["json", "YES"],
};
const stages = ["Fundamental", "Médio", "Superior"];
const publicKeys = ["enunciado", "opcao_a", "opcao_b", "opcao_c", "opcao_d"];

function reportError(error) {
  let message = String(error.sqlMessage || error.message || error.code || "Unknown database error");
  for (const key of ["DB_HOST", "DB_USER", "DB_PASSWORD"]) {
    const value = process.env[key];
    if (value) message = message.split(value).join("[redacted]");
  }
  message = message.replace(/mysql(?:s)?:\/\/\S+/gi, "[redacted connection URI]");
  console.error(`Database operation stopped (${error.code || error.name || "Error"}): ${message}`);
}

(async () => {
  let connection;
  let failed = false;
  try {
    connection = await pool.getConnection();
    const [dbRows] = await connection.query("SELECT DATABASE() AS current_database");
    if (!dbRows[0] || dbRows[0].current_database !== "defaultdb") {
      console.error("Stopped: SELECT DATABASE() did not return defaultdb; no script was executed.");
      process.exitCode = 2;
      return;
    }
    console.log("Pre-write confirmation: SELECT DATABASE() = defaultdb.");

    const scriptPath = path.resolve("..", "database", "schema_e_seed.sql");
    const script = fs.readFileSync(scriptPath, "utf8");
    const statements = script.split(";").map((statement) => statement.trim()).filter(Boolean);
    if (statements.length !== 2 || !/^CREATE\s+TABLE\s+IF\s+NOT\s+EXISTS\s+perguntas\b/i.test(statements[0]) || !/^INSERT\s+INTO\s+perguntas\b/i.test(statements[1])) {
      console.error("Stopped: the existing SQL file did not match the expected two-statement schema/seed script; no script statements were executed.");
      process.exitCode = 2;
      return;
    }
    for (const statement of statements) await connection.query(statement);
    console.log("SQL script application: PASS (existing schema_e_seed.sql executed in defaultdb).");

    const [columns] = await connection.query(
      "SELECT COLUMN_NAME, COLUMN_TYPE, IS_NULLABLE, EXTRA FROM information_schema.COLUMNS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'perguntas' ORDER BY ORDINAL_POSITION",
    );
    const normalizedColumns = new Map(columns.map((column) => [column.COLUMN_NAME, column]));
    let columnsOk = columns.length === Object.keys(expectedColumns).length;
    for (const [name, [type, nullable]] of Object.entries(expectedColumns)) {
      const actual = normalizedColumns.get(name);
      if (!actual || actual.COLUMN_TYPE.toLowerCase() !== type || actual.IS_NULLABLE !== nullable) columnsOk = false;
      if (name === "id" && actual && !actual.EXTRA.toLowerCase().includes("auto_increment")) columnsOk = false;
    }

    const [primaryColumns] = await connection.query(
      "SELECT COLUMN_NAME FROM information_schema.KEY_COLUMN_USAGE WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'perguntas' AND CONSTRAINT_NAME = 'PRIMARY' ORDER BY ORDINAL_POSITION",
    );
