    const checkOk = checkRows.length === 1 && /nivel_estrutural\s+in\s*\(\s*1\s*,\s*2\s*,\s*3\s*\)/.test(checkClause);
    const [indexes] = await connection.query(
      "SELECT INDEX_NAME, NON_UNIQUE, COLUMN_NAME, SEQ_IN_INDEX FROM information_schema.STATISTICS WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'perguntas' AND INDEX_NAME = 'idx_perguntas_etapa_nivel' ORDER BY SEQ_IN_INDEX",
    );
    const indexOk = indexes.length === 2 && Number(indexes[0].NON_UNIQUE) === 1 && indexes[0].COLUMN_NAME === "etapa_escolar" && indexes[1].COLUMN_NAME === "nivel_estrutural";
    const [tableRows] = await connection.query(
      "SELECT ENGINE, TABLE_COLLATION FROM information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = 'perguntas'",
    );
    const tableOk = tableRows.length === 1 && tableRows[0].ENGINE === "InnoDB" && tableRows[0].TABLE_COLLATION === "utf8mb4_unicode_ci";
    const primaryOk = primaryColumns.length === 1 && primaryColumns[0].COLUMN_NAME === "id";
